"""Write engine/entities.js: the HTML5 named character references, as Python's html.unescape knows them.

Run: .venv/bin/python -I tools/make_entities.py
"""
import json
import sys
from html.entities import html5
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / "engine" / "entities.js"

HEAD = """// HTML5 named character references (generated by tools/make_entities.py from Python's
// html.entities.html5; do not edit). Keys with and without the trailing semicolon, as in Python.
(function (g) {
  'use strict';
  const api = """
TAIL = """;
  if (typeof module !== 'undefined') module.exports = api;
  else (g.FCEngine = g.FCEngine || {}).entities = api;
})(typeof window !== 'undefined' ? window : globalThis);
"""


def main() -> int:
    OUT.write_text(HEAD + json.dumps(dict(sorted(html5.items())), ensure_ascii=True, separators=(",", ":")) + TAIL,
                   encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
